import{_ as t,o,c as d,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/architecture.md","filePath":"concepts/architecture.md","lastUpdated":1793733635000}'),c={name:"concepts/architecture.md"};function r(n,e,s,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>kernl is three layers. kehto supplies the primitives, four kernl packages supply the opinions, and one app renders them. Nothing in a lower layer knows about a higher one.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  apps/web  (@kernl/web)                        Astro 7 + Svelte 5    │</span></span>
<span class="line"><span>│  landing site at /         shell at /app/      docs at /docs/        │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  @kernl/core                                   composition root      │</span></span>
<span class="line"><span>│  createKernl · applesauce adapters · decodePointer → resolve →       │</span></span>
<span class="line"><span>│  plan → mount · guard pipeline · grants · describeChange · layouts   │</span></span>
<span class="line"><span>│       │                 │                   │                        │</span></span>
<span class="line"><span>│  @kernl/guard      @kernl/messaging     @kernl/bridges               │</span></span>
<span class="line"><span>│  ingress, gate,    provider contract,   locators, Bridge contract,   │</span></span>
<span class="line"><span>│  focus firewall,   registry, composite  registry, HTTP bridge        │</span></span>
<span class="line"><span>│  CSP, profiles     dm adapter           with SSRF policy             │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  kehto   @kehto/shell · runtime · acl · firewall · services · nip ·  │</span></span>
<span class="line"><span>│          wm                                                          │</span></span>
<span class="line"><span>│  applesauce   EventStore · RelayPool · AccountManager · signers ·    │</span></span>
<span class="line"><span>│               loaders                                                │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  @napplet/core   NAP wire types, NapDomain, envelope dispatch        │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="the-kehto-layer" tabindex="-1">The kehto layer <a class="header-anchor" href="#the-kehto-layer" aria-label="Permalink to &quot;The kehto layer&quot;">​</a></h2><p>kehto is the runtime authority for how a NIP-5D shell composes. kernl uses these seams unchanged:</p><table tabindex="0"><thead><tr><th>kehto package</th><th>What kernl takes from it</th></tr></thead><tbody><tr><td><code>@kehto/shell</code></td><td><code>createShellBridge</code>, <code>buildShellCapabilities</code>, <code>resolveShellEnvironment</code>, <code>prepareNappletSrcdoc</code>, <code>denyNappletControllerAccess</code>, <code>renderNappletFramePolicyMeta</code>, <code>originRegistry</code>, the <code>ShellAdapter</code> hooks and the revocation model.</td></tr><tr><td><code>@kehto/runtime</code></td><td>The protocol engine behind the bridge: dispatch, the ACL gate (<code>bridge.runtime.aclState</code>, <code>ALL_CAPABILITIES</code>), the runtime firewall (<code>bridge.runtime.firewallState</code>), the <code>ServiceRegistry</code> and <code>ConsentRequest</code>.</td></tr><tr><td><code>@kehto/acl</code></td><td>The grant store the runtime enforces, keyed by <code>dTag:hash</code>. kernl reaches it only through <code>bridge.runtime.aclState</code>.</td></tr><tr><td><code>@kehto/firewall</code></td><td>The pure <code>evaluate()</code> engine <code>@kernl/guard</code> runs, and the <code>NappletRules</code> and <code>RateLimit</code> types <code>runtimeFirewallRules</code> translates into.</td></tr><tr><td><code>@kehto/services</code></td><td><code>createRelayPoolService</code>, <code>createIdentityService</code>, <code>createThemeService</code>, <code>createNotifyService</code>, <code>createLinkService</code>, <code>createResourceService</code>, <code>createDmService</code>, <code>createOutboxService</code> and <code>createRelayPoolOutboxRouter</code>.</td></tr><tr><td><code>@kehto/nip</code></td><td><code>resolveNapplet</code>, <code>openNappletArtifactCache</code> and <code>NAPPLET_KINDS</code> from <code>@kehto/nip/5d</code>.</td></tr><tr><td><code>@kehto/wm</code></td><td><code>LayoutStrategy</code>, <code>WindowState</code>, <code>Rect</code> and <code>WindowPlacement</code>, which the layouts implement.</td></tr></tbody></table><p>kernl never re-implements a kehto primitive. When a seam is too narrow, kernl composes in front of it and takes the gap upstream; the four gaps found so far, still to be filed, are in <a href="./../alpha-status#upstream-gaps">Alpha status</a>.</p><h2 id="one-event-layer" tabindex="-1">One event layer <a class="header-anchor" href="#one-event-layer" aria-label="Permalink to &quot;One event layer&quot;">​</a></h2><p>Every relay connection, event store, signer, account and loader goes through applesauce v7 (<a href="./../decisions#d-002">D-002</a>). <code>createKernl</code> creates exactly one of each per shell, or uses the one the host passes in:</p><table tabindex="0"><thead><tr><th>Instance</th><th>Role</th><th>Adapted by</th></tr></thead><tbody><tr><td><code>EventStore</code></td><td>The in-memory, reactive store of every event the shell knows. Applets never receive a reference; <code>createIdentityProviders</code> (<code>applesauce/identity-providers.ts</code>) and <code>lookupReplaceable</code> read from it on their behalf.</td><td>kehto&#39;s identity service and the consent handler.</td></tr><tr><td><code>RelayPool</code></td><td>Every relay connection.</td><td><code>createRelayPoolHooks</code> and <code>createRelayPoolLike</code> (<code>applesauce/relay-hooks.ts</code>) for <code>ShellAdapter.relayPool</code>; <code>createAppletRelayBackend</code>, <code>createDmRelayPool</code> and <code>createOutboxRelayPool</code> (<code>applesauce/relay-backend.ts</code>) for the relay, dm and outbox services. All of them route through <code>selectRelayTier</code>.</td></tr><tr><td><code>AccountManager</code></td><td>The signed-in accounts and their signers.</td><td><code>createKernlAccounts</code> (<code>applesauce/accounts.ts</code>) refuses plaintext-key account types; <code>createAuthHooks</code> and <code>wrapAccountSigner</code> (<code>applesauce/auth-hooks.ts</code>) give kehto a signer that never reveals the account.</td></tr></tbody></table><p><code>nostr-tools</code> remains a transitive peer of kehto and applesauce. kernl source never imports it, and <code>scripts/check-dependency-rules.mjs</code> fails the build if it does.</p><h2 id="the-kernl-packages" tabindex="-1">The kernl packages <a class="header-anchor" href="#the-kernl-packages" aria-label="Permalink to &quot;The kernl packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Depends on</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="./../packages/guard"><code>@kernl/guard</code></a></td><td><code>@kehto/firewall</code></td><td>Flood control, visibility gate, focus-aware firewall, CSP profile, mitigation descriptions. Pure: no DOM, no timers, time is injected.</td></tr><tr><td><a href="./../packages/messaging"><code>@kernl/messaging</code></a></td><td><code>@napplet/core</code> (types)</td><td>The provider contract and the composite backend. Structurally identical to kehto&#39;s <code>DmAdapter</code> so a composite can be handed to <code>createDmService</code> without translation, while the package stays free of a kehto dependency.</td></tr><tr><td><a href="./../packages/bridges"><code>@kernl/bridges</code></a></td><td>nothing</td><td>Locator parsing, the <code>Bridge</code> contract, the registry with its <code>authorize</code> hook, the HTTP bridge.</td></tr><tr><td><a href="./../packages/core"><code>@kernl/core</code></a></td><td>all of the above, kehto, applesauce</td><td>Composition: adapters, the applet lifecycle, the guard pipeline and runtime firewall rules, grants, consent summaries, layouts, the namespaced store. Browser-agnostic; the DOM is reached through <code>KernlHost</code> and <code>FrameLike</code>.</td></tr></tbody></table><p>The three leaf packages have zero framework dependencies and import nothing from each other. Only <code>core</code> composes them. The dependency rules are enforced by <code>pnpm check:deps</code>.</p><h2 id="where-each-nap-domain-is-served-from" tabindex="-1">Where each NAP domain is served from <a class="header-anchor" href="#where-each-nap-domain-is-served-from" aria-label="Permalink to &quot;Where each NAP domain is served from&quot;">​</a></h2><p>An applet reaches the shell through the NAP domains in <code>window.napplet</code>. <code>createKernlServices</code> (<code>kernl-services.ts</code>) registers eight kehto services; <code>shell</code>, <code>inc</code>, <code>storage</code>, <code>keys</code> and <code>media</code> are routed by kehto&#39;s runtime itself. What one applet sees is <code>buildShellCapabilities(adapter).domains</code> narrowed by <code>createEnvironmentResolver(grants)</code>.</p><table tabindex="0"><thead><tr><th>NAP domain</th><th>Served by</th><th>kernl supplies</th><th>Guarded by</th></tr></thead><tbody><tr><td><code>shell</code>, <code>inc</code></td><td>kehto runtime</td><td>the environment from <code>resolveShellEnvironment</code>, narrowed per identity</td><td>identity binding; baseline, no grant needed</td></tr><tr><td><code>storage</code></td><td>kehto runtime</td><td>the ACL state quota (<code>grants.setStateQuota</code>)</td><td>baseline; rate <code>storage:write</code></td></tr><tr><td><code>identity</code></td><td><code>createIdentityService</code></td><td>the active signer through <code>createAuthHooks</code>; profile, follows, mutes and relays from <code>createIdentityProviders</code></td><td>grant (<code>identity:read</code>), &quot;your account&quot; in the shell</td></tr><tr><td><code>theme</code></td><td><code>createThemeService</code></td><td><code>KernlOptions.theme</code> when <code>isTheme</code> accepts it</td><td>baseline</td></tr><tr><td><code>relay</code></td><td><code>createRelayPoolService</code></td><td><code>createAppletRelayBackend</code> over the one pool, routed by <code>selectRelayTier</code></td><td>grant; rates <code>relay:subscribe</code>, <code>relay:publish</code>; subscribe envelope cap</td></tr><tr><td><code>outbox</code></td><td><code>createOutboxService</code></td><td><code>createRelayPoolOutboxRouter</code> over <code>createOutboxRelayPool</code>, relay lists from <code>createIdentityProviders</code>, signing through the active signer (<code>denied:read-only</code> without one)</td><td>grant; rates <code>outbox:subscribe</code>, <code>outbox:publish</code>; consent for destructive kinds</td></tr><tr><td><code>resource</code></td><td><code>createResourceService</code></td><td><code>createBridgeResourceResolver(bridges)</code> with the requesting applet named through <code>resourceInitFor</code></td><td>grant; rate <code>resource:bytes</code>, resource envelope cap, hidden resource allowance, SSRF policy</td></tr><tr><td><code>dm</code></td><td><code>createDmService</code></td><td><code>messaging.composite()</code></td><td>grant; rate <code>dm:send</code>; provider availability</td></tr><tr><td><code>notify</code></td><td><code>createNotifyService</code></td><td><code>host.notify</code> with tone <code>info</code></td><td>grant</td></tr><tr><td><code>link</code></td><td><code>createLinkService</code></td><td><code>host.openLink</code> after <code>LINK_PROTOCOLS</code> (<code>https:</code>, <code>mailto:</code>) allowed it</td><td>grant</td></tr><tr><td><code>keys</code>, <code>media</code></td><td>kehto runtime</td><td>nothing: hotkeys are not forwarded and no media hook is wired</td><td>grant</td></tr></tbody></table><p>So the shell offers thirteen domains: the baseline <code>shell</code>, <code>inc</code>, <code>theme</code> and <code>storage</code>, and <code>identity</code>, <code>relay</code>, <code>outbox</code>, <code>resource</code>, <code>dm</code>, <code>notify</code>, <code>link</code>, <code>keys</code> and <code>media</code> behind a grant. Domains kernl does not serve (<code>config</code>, <code>cvm</code>, <code>upload</code>, <code>intent</code>, <code>fs</code>, <code>llm</code>, <code>cache</code>) have a row in <code>DOMAIN_CAPABILITIES</code> so a grant can be expressed, but the shell does not offer them and <code>grants.allowDomain</code> refuses them with <code>invalid:domain</code>. <a href="./identity-and-grants">Identity and grants</a> explains how the set is narrowed.</p><h2 id="the-mount-path" tabindex="-1">The mount path <a class="header-anchor" href="#the-mount-path" aria-label="Permalink to &quot;The mount path&quot;">​</a></h2><p><code>createAppletLifecycle</code> (<code>kernl-lifecycle.ts</code>) turns an address into a running window in four steps, and the order is load-bearing:</p><ol><li><strong><code>decodePointer(input)</code></strong> (<code>applets/pointer.ts</code>) turns the address into <code>{ kind: &#39;address&#39; | &#39;event&#39;, … }</code> and nothing more. Trust comes from verifying the event, never from the pointer.</li><li><strong><code>resolve(pointer)</code></strong> fetches the manifest from the pointer&#39;s relay hints plus the <code>apps</code> tier (<code>fetchManifestEvent</code>), then verifies the signature and the artifact bytes by hash through <code>resolveApplet</code> over kehto&#39;s <code>resolveNapplet</code> (<code>applets/resolve.ts</code>). Cached bytes are re-hashed on every read. Gateways and caches are accelerators, never identity.</li><li><strong><code>plan(summary)</code></strong> calls <code>grants.ensure(identity)</code>, then <code>planMount</code> (<code>applets/plan.ts</code>): it refuses markup that declares a frame (<code>denied:nested-frame</code>), then builds the environment from <code>resolveShellEnvironment</code>, the guard&#39;s CSP and the namespace prelude inserted by <code>prepareNappletSrcdoc</code>, the Trusted Types directives and frame lock spliced in after them (<a href="./../decisions#d-014">D-014</a>), <code>sandbox: &#39;allow-scripts&#39;</code>, and <code>missingRequired</code>.</li><li><strong><code>mount(plan, frame)</code></strong> installs the profile&#39;s rates in kehto&#39;s runtime firewall with <code>applyRuntimeFirewallRules</code>, then <code>mountApplet</code> (<code>applets/mount.ts</code>) hardens the frame, registers the window in <code>originRegistry</code>, sets the environment, calls <code>bridge.observeFrame</code>, and only then assigns <code>srcdoc</code>. The frame has <code>sandbox=&quot;allow-scripts&quot;</code> and <code>denyNappletControllerAccess</code> applied; it never has <code>src</code> and never <code>allow-same-origin</code>.</li></ol><p>Every revocation reason (<code>window-message</code>, <code>second-hello</code>, <code>invalid-hello</code>, <code>second-load</code>, <code>port-closed</code>, <code>host</code>) and a guard quarantine removes the iframe and drops the guard&#39;s state for that window. <a href="./../policies/security-posture">Security posture</a> lists the rules this path must keep.</p><h2 id="the-app" tabindex="-1">The app <a class="header-anchor" href="#the-app" aria-label="Permalink to &quot;The app&quot;">​</a></h2><p><code>apps/web</code> is Astro 7 with Svelte 5 islands. It owns the landing site at <code>/</code>, the shell at <code>/app/</code>, and the <code>KernlHost</code> that gives <code>@kernl/core</code> a page: <code>localStorage</code>, the consent dialog, notices, link confirmation and window visibility. It creates the iframes, wires <code>window.addEventListener(&#39;message&#39;, kernl.handleWindowMessage)</code> once, and renders the launcher, the grants panel per window, the guard panel and the provider picker. The published packages contain none of this; the app is the only framework-dependent workspace (<a href="./../decisions#d-004">D-004</a>). <code>?preview=1</code> swaps in <code>preview-kernl.ts</code>, which implements the same <code>Kernl</code> contract without a network (<a href="./../decisions#d-011">D-011</a>).</p>`,24)])])}const m=t(c,[["render",r]]);export{u as __pageData,m as default};
